"""Date ranges."""
from datetime import timedelta


def dates_between(start, end, step=1):
    """The dates from `start` to `end`, every `step` days."""
    _validate_step(step)
    direction = 1 if start <= end else -1
    distance = abs((end - start).days)
    return [
        start + timedelta(days=direction * offset)
        for offset in range(0, distance + 1, step)
    ]


def count_dates(start, end, step=1):
    """How many dates `dates_between` returns."""
    _validate_step(step)
    distance = abs((end - start).days)
    return distance // step + 1


def _validate_step(step):
    if type(step) is not int or step < 1:
        raise ValueError("step must be an integer of at least 1")
